    """Connect the largest collinear diagonal group of 1 markers.

    Markers of color 6 lying on that 1 segment remain visible and project
    full parallel-to-the-other-diagonal rays across the grid.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    if len(ones) < 2:
        return out

    # Candidate diagonals: r-c constant (down-right) and r+c constant
    # (down-left). Select the line with the most 1 markers.
    candidates = []
    for slope, key_fn in ((1, lambda r, c: r - c), (-1, lambda r, c: r + c)):
        groups = {}
        for r, c in ones:
            groups.setdefault(key_fn(r, c), []).append((r, c))
        for key, pts in groups.items():
            if len(pts) >= 2:
                candidates.append((len(pts), slope, key, pts))
    if not candidates:
        return out
