    # Fill only the segment bracketed by the selected 1 markers.
    ordered = sorted(pts, key=lambda p: p[0])
    (r0, c0), (r1, c1) = ordered[0], ordered[-1]
    step_c = slope
    for r in range(r0, r1 + 1):
        c = c0 + (r - r0) * step_c
        if 0 <= c < w and out[r][c] != 6:
            out[r][c] = 1

    # A 6 on the selected segment projects a complete perpendicular diagonal.
    seeds = [(r, c) for r in range(r0, r1 + 1)
             for c in [c0 + (r-r0)*step_c]
             if 0 <= c < w and grid[r][c] == 6]
    for sr, sc in seeds:
