            for r in range(h):
                c = sr + sc - r
                if 0 <= c < w:
                    out[r][c] = 6
        else:           # 1 segment down-left; project down-right/up-left.
            for r in range(h):
                c = r + (sc - sr)
                if 0 <= c < w:
                    out[r][c] = 6
    return out


