    """Complete aligned 1 markers; 6s on that segment trace the other diagonal."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # Diagonal lines are indexed by r-c (down-right) or r+c (down-left).
    for slope in (1, -1):
        groups = {}
        for r, c in ones:
            key = r - c if slope == 1 else r + c
            groups.setdefault(key, []).append((r, c))
        for key, pts in groups.items():
            if len(pts) < 2:
                continue
            pts.sort()
            (r0, c0), (r1, c1) = pts[0], pts[-1]
            segment = set()
            for r in range(r0, r1 + 1):
                c = c0 + slope * (r - r0)
                segment.add((r, c))
                if out[r][c] != 6:
                    out[r][c] = 1
            # A 6 lying on the completed 1 segment projects a full
            # perpendicular diagonal of 6s across the grid.
            for sr, sc in sixes:
                if (sr, sc) not in segment:
                    continue
                for r in range(h):
                    c = sr + sc - r if slope == 1 else r + sc - sr
                    if 0 <= c < w:
                        out[r][c] = 6
    return out


